  }
  return result;
}

resolveToClass(Type t, Map<TypeVariable<?>,Type> map) {
  if (t instanceof Class<?>) {
    return (Class<?>) t;
  } else if (t instanceof ParameterizedType) {
    return (Class<?>) ((ParameterizedType) t).getRawType();
  } else if (t instanceof TypeVariable) {
    Type resolved = map.get(t);
    if (resolved == null) {
      return null;
    }
    return resolveToClass(resolved, map);
  } else if (t instanceof WildcardType) {
    // choose upper bound
    WildcardType wc = (WildcardType) t;
    Type[] bounds = wc.getUpperBounds();
    if (bounds.length > 0) {
      return resolveToClass(bounds[0], map);
    }
    return null;
  } else {
    return null;
  }
}

