protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        return new GraphWalk<>(graph, new ArrayList<>(), new ArrayList<>());
    }
    // Make a mutable copy of the set of edges
    Set<E> remaining = new HashSet<>(tour);
    // Pick an arbitrary edge to start
    E startEdge = remaining.iterator().next();
    remaining.remove(startEdge);

    V startVertex = graph.getEdgeSource(startEdge);
    V nextVertex = graph.getEdgeTarget(startEdge);

    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();

    // Initialize the path with the first edge
    vertices.add(startVertex);
    vertices.add(nextVertex);
    edges.add(startEdge);

    V currentVertex = nextVertex;
    // Traverse remaining edges
    while (!remaining.isEmpty()) {
        boolean found = false;
        for (E e : remaining) {
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(currentVertex)) {
                vertices.add(tgt);
                edges.add(e);
                currentVertex = tgt;
                remaining.remove(e);
                found = true;
                break;
            } else if (tgt.equals(currentVertex)) {
                vertices.add(src);
                edges.add(e);
                currentVertex = src;
                remaining.remove(e);
                found = true;
                break;
            }
        }
        if (!found) {
            throw new IllegalArgumentException("Edges do not form a continuous tour.");
        }
    }
    // Ensure the path is closed (start == end). If not, add the start vertex to close it.
    if (!currentVertex.equals(startVertex)) {
        vertices.add(startVertex);
    }
    return new GraphWalk<>(graph, vertices, edges);
}

